function [p_g, v_c, i_c_out] = mfun_gfm_current_reference(p_g_ref, v_c_ref, fbk_in, p)
%MFUN_GFM_CURRENT_REFERENCE Block compute_output of the control system.
%   Generated by motulator_export from the MATLAB port of motulator. The parameters are
%   the fields of the struct p (from the mask, [] as NaN).
fbk = gfm_feedbacks_unpack(fbk_in);
ref = gfm_current_reference(p.R_a, p.k_v, p.k_c, p_g_ref, v_c_ref, fbk);
p_g = ref.p_g;
v_c = ref.v_c;
i_c = ref.i_c;
i_c_out = complex_out(i_c);
end

function s = gfm_feedbacks_unpack(u)
%GFM_FEEDBACKS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_c', complex(u(1), u(2)), ...
    'u_c', complex(u(3), u(4)), ...
    'u_c_zoh', complex(u(5), u(6)), ...
    'v_c', complex(u(7), u(8)), ...
    'u_g', complex(u(9), u(10)), ...
    'p_g', u(11), ...
    'q_g', u(12), ...
    'theta_c', u(13), ...
    'w_c', u(14));
end

function y = complex_out(z)
%COMPLEX_OUT Signal [real part; imaginary part] of a complex number.
y = [real(z); imag(z)];
end

function ref = gfm_current_reference(R_a, k_v, k_c, p_g_ref, v_c_ref, fbk)
%GFM_CURRENT_REFERENCE References p_g and v_c and the current reference i_c of the
%   transparent current limitation (ObserverBasedGridFormingController.
%   compute_output before the CurrentLimiter), R_a being the active resistance, k_v
%   the voltage control gain, and k_c the current control gain.
% Complex gains and the feedback correction for the grid-forming mode
exp_j_theta = exp(1i*angle(fbk.v_c));
k_p = exp_j_theta*R_a/(1.5*v_c_ref);
k_vc = exp_j_theta*(1 - 1i*k_v);
e_c = k_p*(p_g_ref - fbk.p_g) + k_vc*(v_c_ref - abs(fbk.v_c));
% Current reference of the transparent current limitation
ref = struct('p_g', p_g_ref, 'v_c', v_c_ref, 'i_c', fbk.i_c + e_c/k_c);
end
